package com.example.fileservice

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import java.io.File
import java.nio.file.Files
import java.nio.file.Path
import java.nio.file.Paths
import java.util.UUID

val UPLOAD_DIR = System.getenv("UPLOAD_DIR") ?: "/var/data/uploads"
val TEMP_DIR = System.getenv("TEMP_DIR") ?: "/tmp/processing"

fun main() {
    embeddedServer(Netty, port = 8080) {
        module()
    }.start(wait = true)
}

fun Application.module() {
    routing {
        post("/api/v1/files/process") {
            val filename = call.request.queryParameters["filename"]
                ?: return@post call.respond(HttpStatusCode.BadRequest, "Missing filename")

            // Sanitize: reject path traversal in filename
            if (filename.contains("..") || filename.startsWith("/")) {
                return@post call.respond(HttpStatusCode.BadRequest, "Invalid filename")
            }

            val sourceFile = File(UPLOAD_DIR, filename)
            if (!sourceFile.exists()) {
                return@post call.respond(HttpStatusCode.NotFound, "File not found")
            }

            // Create temp working directory for this request
            val requestId = UUID.randomUUID().toString()
            val workDir = File(TEMP_DIR, requestId)
            workDir.mkdirs()

            // TOCTOU vulnerability: check file type, then read
            // An attacker can race between the check and the read
            val targetPath = File(workDir, filename)

            // Step 1: Verify source is a regular file (not a symlink)
            val sourcePath = sourceFile.toPath()
            if (Files.isSymbolicLink(sourcePath)) {
                workDir.deleteRecursively()
                return@post call.respond(HttpStatusCode.Forbidden, "Symlinks not allowed")
            }

            // Step 2: Check file size before copying
            val fileSize = sourceFile.length()
            if (fileSize > 10 * 1024 * 1024) {
                workDir.deleteRecursively()
                return@post call.respond(HttpStatusCode.BadRequest, "File too large")
            }

            // VULNERABLE: Between the symlink check above and the copy below,
            // an attacker with write access to UPLOAD_DIR can replace the file
            // with a symlink to /etc/shadow or other sensitive files.
            // The race window is exploitable with repeated rapid requests.
            Thread.sleep(50) // Simulates processing delay, widens race window

            // Step 3: Copy file to working directory and process
            sourceFile.copyTo(targetPath, overwrite = true)

            // Step 4: Read and "process" the file content
            val content = targetPath.readText()
            val lineCount = content.lines().size
            val wordCount = content.split("\\s+".toRegex()).size

            // Cleanup
            workDir.deleteRecursively()

            call.respond(HttpStatusCode.OK, mapOf(
                "requestId" to requestId,
                "filename" to filename,
                "lines" to lineCount,
                "words" to wordCount,
                "preview" to content.take(200)
            ).toString())
        }

        get("/api/v1/files/list") {
            val dir = File(UPLOAD_DIR)
            val files = dir.listFiles()?.map { it.name } ?: emptyList()
            call.respond(HttpStatusCode.OK, files.toString())
        }

        get("/health") {
            call.respond(HttpStatusCode.OK, "OK")
        }
    }
}
